To get the window width and height and automatically update when they change, use the `useWindowDimensions` hook. It "automatically updates all of its values when screen size or font scale changes" [6].

```tsx
import {useWindowDimensions} from 'react-native';

const {height, width} = useWindowDimensions();
```

Alternatively, if you use the `Dimensions` module, you can listen for changes using `Dimensions.addEventListener` [3][7]:

```tsx
import {useState, useEffect} from 'react';
import {Dimensions, type DimensionsPayload} from 'react-native';

const App = () => {
  const [dimensions, setDimensions] = useState({
    window: Dimensions.get('window'),
    screen: Dimensions.get('screen'),
  });

  useEffect(() => {
    const subscription = Dimensions.addEventListener(
      'change',
      ({window, screen}: DimensionsPayload) => {
        if (window && screen) {
          setDimensions({window, screen});
        }
      },
    );
    return () => subscription?.remove();
  }, []);

  //...
};
```

